    <div class="breadcrumbs"><a href="<?= e(url()) ?>">Beranda</a><span>/</span><a href="<?= e(url('pages/product.php?kategori=' . rawurlencode($product['kategori']))) ?>"><?= e($product['kategori']) ?></a><span>/</span> Detail produk</div><section class="product-detail"><div class="detail-image"><img src="<?= e(url($product['img'])) ?>" alt="<?= e($product['nama_barang']) ?>"></div><div class="detail-copy"><span class="eyebrow"><?= e($product['merk'] . ' / ' . $product['kategori']) ?></span><h1><?= e($product['nama_barang']) ?></h1><p class="rating"><span>★</span> <?= count($reviews) ? number_format(array_sum(array_column($reviews,'rating'))/count($reviews),1) : 'Belum ada ulasan' ?> · <?= count($reviews) ?> ulasan · <?= (int)$product['terjual'] ?> terjual</p><div class="detail-price"><?= rupiah($product['harga']) ?></div><span class="badge <?= $product['stok'] > 0 ? 'success' : 'danger' ?>"><?= (int)$product['stok'] ?> stok tersedia</span><form method="post" class="purchase-form"><?= csrf() ?><?php field('Jumlah', 'qty', 1, 'number', 'min="1" max="' . max(1,(int)$product['stok']) . '" required'); ?><div class="button-row"><button class="button" name="action" value="cart" <?= $product['stok']<1?'disabled':'' ?>><?= icon('bag') ?> Tambah ke keranjang</button><button class="button secondary" name="action" value="buy" <?= $product['stok']<1?'disabled':'' ?>>Beli sekarang</button></div></form><p class="muted small-text"><?= icon('truck') ?> Pilih jasa pengiriman saat checkout.</p></div></section><section class="panel section"><h2>Detail yang perlu Anda tahu.</h2><p class="description"><?= nl2br(e($product['keterangan'])) ?></p></section><section class="section"><h2>Ulasan pelanggan</h2><?php if (!$reviews): ?><p class="muted">Belum ada ulasan untuk produk ini.</p><?php endif; ?><div class="review-grid"><?php foreach ($reviews as $review): ?><article class="panel"><strong><?= e($review['nama']) ?></strong><p class="rating"><span><?= str_repeat('★',(int)$review['rating']) ?></span></p><p><?= e($review['ulasan']) ?></p><?php if ($review['foto']): ?><img class="review-image" src="<?= e(url($review['foto'])) ?>" alt="Foto ulasan pelanggan"><?php endif; ?></article><?php endforeach; ?></div></section>
